package com.bank.gc.model;

// Describes a workload: heap size and whether low latency is critical.
public class Workload {
    private final String name;
    private final int heapGb;
    private final boolean latencySensitive;
    private final int maxAcceptablePauseMs;

    public Workload(String name, int heapGb, boolean latencySensitive, int maxAcceptablePauseMs) {
        this.name = name;
        this.heapGb = heapGb;
        this.latencySensitive = latencySensitive;
        this.maxAcceptablePauseMs = maxAcceptablePauseMs;
    }

    public String getName() { return name; }
    public int getHeapGb() { return heapGb; }
    public boolean isLatencySensitive() { return latencySensitive; }
    public int getMaxAcceptablePauseMs() { return maxAcceptablePauseMs; }
}
