import com.bank.gc.model.Workload;

// Each collector models its pause (ms) for a given heap, and its flag.
public interface Collector {
    long estimatedPauseMs(Workload w);  // rough pause model for the heap size
    String flag();                      // the JVM flag to enable it
    String name();
}
