package com.bank.gc.collector;

import com.bank.gc.model.Workload;

// Single-threaded, full stop-the-world. Pause scales hard with heap.
public class SerialGc implements Collector {
    @Override public long estimatedPauseMs(Workload w) { return 80L * w.getHeapGb(); }
    @Override public String flag() { return "-XX:+UseSerialGC"; }
    @Override public String name() { return "Serial"; }
}
