package com.bank.gc.collector;

import com.bank.gc.model.Workload;

// Multi-threaded stop-the-world: best throughput, pauses still scale with heap.
public class ParallelGc implements Collector {
    @Override public long estimatedPauseMs(Workload w) { return 25L * w.getHeapGb(); }
    @Override public String flag() { return "-XX:+UseParallelGC"; }
    @Override public String name() { return "Parallel"; }
