package com.bank.gc.collector;

import com.bank.gc.model.Workload;

// Region-based, mostly concurrent, targets a bounded pause (~tens of ms).
public class G1Gc implements Collector {
    @Override public long estimatedPauseMs(Workload w) {
        return Math.min(200, 10L + 2L * w.getHeapGb()); // bounded, grows slowly
    }
    @Override public String flag() { return "-XX:+UseG1GC"; }
    @Override public String name() { return "G1"; }
}
