package com.bank.gc.collector;

import com.bank.gc.model.Workload;

// Almost fully concurrent: sub-ms pauses that DO NOT grow with heap size.
public class ZGc implements Collector {
    @Override public long estimatedPauseMs(Workload w) { return 1L; } // ~constant
    @Override public String flag() { return "-XX:+UseZGC -XX:+ZGenerational"; }
    @Override public String name() { return "ZGC"; }
}
