package com.bank.gc.advisor;

import com.bank.gc.collector.*;
import com.bank.gc.model.Workload;
import java.util.List;
import java.util.logging.Logger;

// Recommends a collector: latency-sensitive → lowest pause that fits the SLO;
// otherwise → highest throughput (Parallel) for the heap.
public class GcAdvisor {
    private static final Logger log = Logger.getLogger(GcAdvisor.class.getName());
    private final List<Collector> collectors = List.of(
        new SerialGc(), new ParallelGc(), new G1Gc(), new ZGc());

    public Collector recommend(Workload w) {
        log.info(() -> "=== workload '" + w.getName() + "' heap=" + w.getHeapGb()
                + "g latencySensitive=" + w.isLatencySensitive()
                + " maxPause=" + w.getMaxAcceptablePauseMs() + "ms ===");
        for (Collector c : collectors) {
            long pause = c.estimatedPauseMs(w);
            log.info(() -> "  " + c.name() + " estimated pause ~" + pause + "ms");
        }
        Collector chosen;
        if (!w.isLatencySensitive()) {
            // Throughput job: Parallel maximizes useful work.
            chosen = new ParallelGc();
        } else {
            // Latency job: pick the lowest-pause collector meeting the SLO.
            chosen = collectors.stream()
                .filter(c -> c.estimatedPauseMs(w) <= w.getMaxAcceptablePauseMs())
                .min((a, b) -> Long.compare(a.estimatedPauseMs(w), b.estimatedPauseMs(w)))
                .orElse(new G1Gc());
        }
        Collector result = chosen;
        log.info(() -> "  → recommend " + result.name() + "  (" + result.flag() + ")");
        return chosen;
    }
}
