package com.bank.gc;

import com.bank.gc.advisor.GcAdvisor;
import com.bank.gc.model.Workload;

public class GcDemo {
    public static void main(String[] args) {
        GcAdvisor advisor = new GcAdvisor();

        // Batch: large heap, NOT latency sensitive → throughput wins.
        advisor.recommend(new Workload("settlement-batch", 8, false, 1000));

        // API: 10g heap, latency sensitive, 100ms budget → G1 fits.
        advisor.recommend(new Workload("account-api", 10, true, 100));

        // Trading: 64g heap, must stay under 1ms → ZGC.
        advisor.recommend(new Workload("trading-engine", 64, true, 1));
    }
}
